def _events_for(session, user_id) -> list[ClientEvent]:
    return session.query(ClientEvent).filter(ClientEvent.user_id == user_id).all()


# --- Positive: add-allotment mode (D-4 additive) --------------------------------------


def test_add_allotment_on_existing_subscription_increments_additively(session):
    client = make_client(session)
    model = make_model(session, model_size=Decimal("1000000"))
    make_subscription(session, client, model, multiplier=Decimal("3"))
    make_portfolio(session, client, cash_deposit=Decimal("5000000"), amount_in_trade=Decimal("0"))

    svc = OnboardingService(session)
    req = SubmitAllotmentReq(client_id=client.id, model_id=model.id, multiplier=Decimal("2"))
    dto = svc.submit_allotment(req)

    sub = session.get(ClientSubscription, (client.id, model.id))
    assert sub.multiplier == Decimal("5")
    assert dto.kind == "allotment"
    assert dto.status == "pending"


