# --- Positive: allotment row / event / portfolio shift (D-1) --------------------------


def test_full_write_set_lands_atomically(session):
    client = make_client(session)
    model = make_model(session, model_size=Decimal("1000000"))
    make_portfolio(
        session,
        client,
        cash_deposit=Decimal("5000000"),
        amount_in_trade=Decimal("0"),
        previous_amount_in_trade=Decimal("0"),
    )

    svc = OnboardingService(session)
    req = SubmitAllotmentReq(client_id=client.id, model_id=model.id, multiplier=Decimal("2"))
    dto = svc.submit_allotment(req)

    allotment = svc.repo.get_allotment(dto.id)
    assert allotment.kind == AllotRdmpKind.ALLOTMENT
    assert allotment.status == AllotRdmpStatus.PENDING
    assert allotment.agg_after - allotment.agg_before == Decimal("2")

    events = _events_for(session, client.id)
    assert len(events) == 1

    portfolio = session.get(ClientPortfolio, client.id)
    amount = Decimal("2") * Decimal("1000000")
    assert portfolio.cash_deposit == Decimal("5000000") - amount
    assert portfolio.amount_in_trade == amount
    assert portfolio.previous_amount_in_trade == amount


