# --- Invariants -------------------------------------------------------------------------


def test_agg_before_read_before_upsert_holds_across_sequential_submits(session):
    """Two different clients submitting allotments in the same model, in
    sequence -- the second call's agg_before must reflect the first call's
    already-committed subscription, not double-count or miss it."""
    model = make_model(session, model_size=Decimal("1000000"))
    client_a = make_client(session, name="Client A")
    client_b = make_client(session, name="Client B")
    make_portfolio(session, client_a, cash_deposit=Decimal("5000000"))
    make_portfolio(session, client_b, cash_deposit=Decimal("5000000"))

    svc = OnboardingService(session)
    dto_a = svc.submit_allotment(
        SubmitAllotmentReq(client_id=client_a.id, model_id=model.id, multiplier=Decimal("2"))
    )
    dto_b = svc.submit_allotment(
        SubmitAllotmentReq(client_id=client_b.id, model_id=model.id, multiplier=Decimal("3"))
    )

    assert dto_a.agg_before == 0.0
    assert dto_a.agg_after == 2.0
    assert dto_b.agg_before == 2.0
    assert dto_b.agg_after == 5.0


def test_forced_failure_after_subscription_upsert_rolls_back_everything(session, monkeypatch):
    client = make_client(session)
    model = make_model(session, model_size=Decimal("1000000"))
    make_portfolio(session, client, cash_deposit=Decimal("5000000"))

    svc = OnboardingService(session)

    def _boom(*args, **kwargs):
        raise RuntimeError("forced failure")

    monkeypatch.setattr(svc.repo, "create_event", _boom)

    req = SubmitAllotmentReq(client_id=client.id, model_id=model.id, multiplier=Decimal("2"))
    with pytest.raises(RuntimeError):
        svc.submit_allotment(req)

    # subscription upsert must have been rolled back along with everything else
    assert session.get(ClientSubscription, (client.id, model.id)) is None
    portfolio = session.get(ClientPortfolio, client.id)
    assert portfolio.cash_deposit == Decimal("5000000")
    assert portfolio.amount_in_trade == Decimal("0")


def test_resubscribe_after_full_redemption_with_a_different_account_is_rejected(session):
    """The invariant client_ib_accounts exists for: there is no real
    unsubscription. A full redemption DELETES the client_subscriptions row but
    the (user_id, model_id) IB-account row is permanent. Resubscribing with a
    DIFFERENT account string must be rejected loudly -- with the field now
    required on the form, a silent ignore would look like success while the
    typed value is discarded. See client_ib_accounts.ensure."""
    client = make_client(session)
    model = make_model(session, model_size=Decimal("1000000"))
    make_portfolio(session, client, cash_deposit=Decimal("10000000"), amount_in_trade=Decimal("0"))
    svc = OnboardingService(session)
    original_ib = make_ib()

    svc.submit_allotment(
        SubmitAllotmentReq(
            client_id=client.id,
            model_id=model.id,
            multiplier=Decimal("5"),
            client_ib=original_ib,
        )
    )

    # Full redemption of all 5 units -> _execute_redemption_approval deletes the
    # subscription (remaining <= 0), same path test_be4_pc_decide.py drives.
    redemption = svc.repo.create_allotment(
        user_id=client.id,
        model_id=model.id,
        multiplier=Decimal("5"),
        agg_before=Decimal("5"),
        agg_after=Decimal("0"),
        kind=AllotRdmpKind.REDEMPTION,
        status=AllotRdmpStatus.AWAITING_PC,
        note="full redemption",
    )
    session.commit()
    svc.pc_decide_redemption(
        redemption.id, RedemptionDecisionReq(verdict="approve"), decided_by="pc-uid"
    )
    assert session.get(ClientSubscription, (client.id, model.id)) is None

    # Resubscribe with a DIFFERENT account string -- must raise, not silently
    # discard it.
    with pytest.raises(HTTPException) as excinfo:
        svc.submit_allotment(
            SubmitAllotmentReq(
                client_id=client.id,
                model_id=model.id,
                multiplier=Decimal("2"),
                client_ib=make_ib(),
            )
        )
    assert excinfo.value.status_code == status.HTTP_409_CONFLICT

    rows = (
        session.query(ClientIbAccount)
        .filter_by(user_id=client.id, model_id=model.id)
        .all()
    )
    assert len(rows) == 1
    assert rows[0].ib_account == original_ib


def test_resubscribe_after_full_redemption_with_the_same_account_inherits_it(session):
    """Retyping the SAME account the client already holds is not a conflict --
    it passes both client_ib_accounts.check's self-match and ensure's
    different-value guard, and the permanent row is simply reused."""
    client = make_client(session)
    model = make_model(session, model_size=Decimal("1000000"))
    make_portfolio(session, client, cash_deposit=Decimal("10000000"), amount_in_trade=Decimal("0"))
    svc = OnboardingService(session)
    original_ib = make_ib()

    svc.submit_allotment(
        SubmitAllotmentReq(
            client_id=client.id,
            model_id=model.id,
            multiplier=Decimal("5"),
            client_ib=original_ib,
        )
    )
    redemption = svc.repo.create_allotment(
        user_id=client.id,
        model_id=model.id,
        multiplier=Decimal("5"),
        agg_before=Decimal("5"),
        agg_after=Decimal("0"),
        kind=AllotRdmpKind.REDEMPTION,
        status=AllotRdmpStatus.AWAITING_PC,
        note="full redemption",
    )
    session.commit()
    svc.pc_decide_redemption(
        redemption.id, RedemptionDecisionReq(verdict="approve"), decided_by="pc-uid"
    )
    assert session.get(ClientSubscription, (client.id, model.id)) is None

    # Resubscribe with the SAME account (any case/whitespace) -- must not raise.
    svc.submit_allotment(
        SubmitAllotmentReq(
            client_id=client.id,
            model_id=model.id,
            multiplier=Decimal("2"),
            client_ib=f" {original_ib.lower()} ",
        )
    )

    rows = (
        session.query(ClientIbAccount)
        .filter_by(user_id=client.id, model_id=model.id)
        .all()
    )
    assert len(rows) == 1
    assert rows[0].ib_account == original_ib


